* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: #fafafa;
  color: #222;
}

#app {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  padding: 16px 20px;
  gap: 12px;
}

header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

header h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 600;
  color: #1a1a1a;
}

header p {
  margin: 0;
  font-size: 13px;
  color: #666;
}

#main {
  display: flex;
  flex-direction: row;
  gap: 18px;
  flex: 1 1 auto;
  min-height: 0;
}

#chart-panel {
  flex: 1 1 65%;
  background: #ffffff;
  border: 1px solid #e2e2e2;
  border-radius: 8px;
  padding: 12px 12px 6px 12px;
  display: flex;
  flex-direction: column;
  min-width: 0;
}

#bubble-chart {
  width: 100%;
  height: 640px;
  display: block;
  cursor: grab;
}

#bubble-chart:active {
  cursor: grabbing;
}

.bubble {
  cursor: pointer;
  stroke: #ffffff;
  stroke-width: 1.5;
}

.bubble.is-etf {
  stroke-dasharray: 4 3;
}

.bubble.is-selected {
  stroke: #222222;
  stroke-width: 3;
}

.bubble-label {
  pointer-events: none;
  font-size: 10px;
  font-weight: 600;
  fill: #ffffff;
  text-anchor: middle;
  dominant-baseline: central;
  text-shadow: 0 0 2px rgba(0, 0, 0, 0.45);
}

.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  padding: 10px 4px 4px 4px;
  font-size: 12px;
  color: #333;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid rgba(0, 0, 0, 0.15);
}

#table-panel {
  flex: 1 1 35%;
  background: #ffffff;
  border: 1px solid #e2e2e2;
  border-radius: 8px;
  padding: 12px;
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: 700px;
}

#table-panel h2 {
  margin: 0 0 8px 0;
  font-size: 15px;
  font-weight: 600;
  color: #1a1a1a;
}

#table-scroll {
  flex: 1 1 auto;
  overflow-y: auto;
  overflow-x: auto;
  border: 1px solid #ececec;
  border-radius: 6px;
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #f6f7f9;
  border-bottom: 1px solid #d8d8d8;
  text-align: left;
  padding: 8px 10px;
  font-weight: 600;
  color: #333;
  z-index: 1;
}

#stock-table tbody td {
  padding: 7px 10px;
  border-bottom: 1px solid #f0f0f0;
  vertical-align: middle;
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background-color 0.12s ease;
}

#stock-table tbody tr:hover {
  background: #f5f8ff;
}

#stock-table tbody tr.is-selected {
  background: #fff3bf;
}

#stock-table tbody tr.is-selected td {
  font-weight: 600;
}

.ticker-cell {
  font-weight: 700;
  color: #1a1a1a;
}

.sector-cell {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sector-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  display: inline-block;
  border: 1px solid rgba(0, 0, 0, 0.18);
}

.mcap-cell {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

#tooltip {
  position: absolute;
  pointer-events: none;
  background: rgba(20, 20, 20, 0.92);
  color: #fff;
  padding: 8px 10px;
  border-radius: 6px;
  font-size: 12px;
  line-height: 1.4;
  max-width: 280px;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
  opacity: 0;
  transform: translate(-50%, -110%);
  transition: opacity 0.12s ease;
  z-index: 1000;
}

#tooltip .tt-ticker {
  font-weight: 700;
  font-size: 13px;
  margin-bottom: 2px;
}

#tooltip .tt-sector {
  font-size: 11px;
  opacity: 0.85;
  margin-top: 2px;
}

(function () {
  "use strict";

  const DATA_URL = "data/stock-descriptions.csv";
  const SECTOR_ORDER = [
    "Information Technology",
    "Industry",
    "Energy",
    "Financial",
    "ETF"
  ];

  const SECTOR_COLORS = {
    "Information Technology": "#1f77b4",
    "Industry": "#ff7f0e",
    "Energy": "#2ca02c",
    "Financial": "#d62728",
    "ETF": "#9467bd"
  };

  const state = {
    nodes: [],
    selectedTicker: null,
    simulation: null,
    svg: null,
    bubbleGroup: null,
    width: 0,
    height: 0,
    sectorCenters: {}
  };

  document.addEventListener("DOMContentLoaded", init);

  async function init() {
    try {
      const raw = await d3.csv(DATA_URL);
      state.nodes = prepareNodes(raw);
    } catch (err) {
      console.error("Failed to load stock data:", err);
      document.getElementById("chart-panel").innerHTML =
        '<p style="color:#a00;padding:12px;">Failed to load data: ' + err.message + "</p>";
      return;
    }

    renderTable(state.nodes);
    renderChart(state.nodes);
  }

  function prepareNodes(raw) {
    return raw.map((row) => {
      const ticker = row.ticker;
      const sector = row.sector;
      const name = row["full name"];
      const marketCapRaw = row.marketCap;
      const marketCap = marketCapRaw && marketCapRaw !== ""
        ? parseFloat(marketCapRaw)
        : null;
      const isEtf = sector === "ETF";
      return {
        ticker: ticker,
        sector: sector,
        name: name,
        marketCap: marketCap,
        isEtf: isEtf
      };
    });
  }

  function formatMarketCap(value) {
    if (value === null || value === undefined || isNaN(value)) return "—";
    const abs = Math.abs(value);
    if (abs >= 1e12) return (value / 1e12).toFixed(2) + "T";
    if (abs >= 1e9) return (value / 1e9).toFixed(2) + "B";
    if (abs >= 1e6) return (value / 1e6).toFixed(2) + "M";
    if (abs >= 1e3) return (value / 1e3).toFixed(2) + "K";
    return String(value);
  }

  function renderTable(nodes) {
    const tbody = document.querySelector("#stock-table tbody");
    tbody.innerHTML = "";
    nodes.forEach((n) => {
      const tr = document.createElement("tr");
      tr.dataset.ticker = n.ticker;

      const tdTicker = document.createElement("td");
      tdTicker.className = "ticker-cell";
      tdTicker.textContent = n.ticker;
      tr.appendChild(tdTicker);

      const tdName = document.createElement("td");
      tdName.textContent = n.name;
      tr.appendChild(tdName);

      const tdSector = document.createElement("td");
      const sectorWrap = document.createElement("span");
      sectorWrap.className = "sector-cell";
      const dot = document.createElement("span");
      dot.className = "sector-dot";
      dot.style.background = SECTOR_COLORS[n.sector] || "#888";
      sectorWrap.appendChild(dot);
      sectorWrap.appendChild(document.createTextNode(n.sector));
      tdSector.appendChild(sectorWrap);
      tr.appendChild(tdSector);

      const tdMcap = document.createElement("td");
      tdMcap.className = "mcap-cell";
      tdMcap.textContent = formatMarketCap(n.marketCap);
      tr.appendChild(tdMcap);

      tr.addEventListener("click", () => selectTicker(n.ticker, { source: "table" }));
      tbody.appendChild(tr);
    });
  }

  function renderChart(nodes) {
    const container = document.getElementById("chart-panel");
    container.style.position = "relative";

    const tooltip = document.createElement("div");
    tooltip.id = "tooltip";
    container.appendChild(tooltip);

    const legend = document.createElement("div");
    legend.className = "legend";
    SECTOR_ORDER.forEach((sector) => {
      const item = document.createElement("div");
      item.className = "legend-item";
      const swatch = document.createElement("span");
      swatch.className = "legend-swatch";
      swatch.style.background = SECTOR_COLORS[sector];
      item.appendChild(swatch);
      item.appendChild(document.createTextNode(sector));
      legend.appendChild(item);
    });
    container.appendChild(legend);

    const svgEl = document.getElementById("bubble-chart");
    const svg = d3.select(svgEl);
    state.svg = svg;
    state.bubbleGroup = svg.append("g").attr("class", "bubbles");

    const resize = () => {
      const rect = svgEl.getBoundingClientRect();
      state.width = rect.width;
      state.height = rect.height;
      svg.attr("viewBox", `0 0 ${rect.width} ${rect.height}`);
      if (state.simulation) {
        state.simulation.force("center", d3.forceCenter(rect.width / 2, rect.height / 2));
        recomputeSectorCenters(rect.width, rect.height);
        state.simulation.alpha(0.6).restart();
      }
    };
    resize();
    window.addEventListener("resize", resize);

    recomputeSectorCenters(state.width, state.height);

    const radiusScale = d3.scaleSqrt()
      .domain([0, d3.max(nodes, (n) => n.marketCap || 0) || 1])
      .range([12, 38]);

    const ETF_RADIUS = 16;

    nodes.forEach((n) => {
      n.radius = n.isEtf
        ? ETF_RADIUS
        : Math.max(10, radiusScale(n.marketCap || 0));
    });

    const simulation = d3.forceSimulation(nodes)
      .force("collide", d3.forceCollide().radius((d) => d.radius + 2).iterations(2))
      .force("x", d3.forceX((d) => state.sectorCenters[d.sector].x).strength(0.18))
      .force("y", d3.forceY((d) => state.sectorCenters[d.sector].y).strength(0.18))
      .force("center", d3.forceCenter(state.width / 2, state.height / 2))
      .stop();

    for (let i = 0; i < 300; i++) simulation.tick();
    runSimulation(simulation, nodes);

    const groups = state.bubbleGroup.selectAll("g.bubble-node")
      .data(nodes, (d) => d.ticker)
      .enter()
      .append("g")
      .attr("class", "bubble-node")
      .attr("data-ticker", (d) => d.ticker);

    groups.append("circle")
      .attr("class", (d) => "bubble" + (d.isEtf ? " is-etf" : ""))
      .attr("r", (d) => d.radius)
      .attr("fill", (d) => SECTOR_COLORS[d.sector] || "#888")
      .on("mouseover", (event, d) => onBubbleHover(event, d, tooltip))
      .on("mousemove", (event, d) => onBubbleHover(event, d, tooltip))
      .on("mouseout", () => onBubbleOut(tooltip))
      .on("click", (event, d) => selectTicker(d.ticker, { source: "bubble" }));

    groups.append("text")
      .attr("class", "bubble-label")
      .attr("text-anchor", "middle")
      .attr("dominant-baseline", "central")
      .text((d) => d.ticker);

    groups.attr("transform", (d) => `translate(${d.x},${d.y})`);

    simulation.on("tick", () => {
      nodes.forEach((d) => {
        d.x = clamp(d.x, d.radius, state.width - d.radius);
        d.y = clamp(d.y, d.radius, state.height - d.radius);
      });
      groups.attr("transform", (d) => `translate(${d.x},${d.y})`);
    });
  }

  function recomputeSectorCenters(width, height) {
    const sectors = SECTOR_ORDER.filter((s) => s in SECTOR_COLORS);
    const count = sectors.length;
    const padding = 80;
    const usableW = Math.max(120, width - padding * 2);
    const usableH = Math.max(120, height - padding * 2);
    const cols = Math.ceil(Math.sqrt(count));
    const rows = Math.ceil(count / cols);
    const cellW = usableW / Math.max(1, cols - 1 || 1);
    const cellH = usableH / Math.max(1, rows - 1 || 1);
    sectors.forEach((sector, i) => {
      const r = Math.floor(i / cols);
      const c = i % cols;
      state.sectorCenters[sector] = {
        x: padding + (cols === 1 ? 0 : c * cellW),
        y: padding + (rows === 1 ? 0 : r * cellH)
      };
    });
  }

  function runSimulation(simulation, nodes) {
    simulation.nodes(nodes);
    simulation.alpha(1).restart();
    for (let i = 0; i < 200; i++) simulation.tick();
    simulation.stop();
  }

  function clamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function onBubbleHover(event, d, tooltip) {
    if (d.isEtf) {
      onBubbleOut(tooltip);
      return;
    }
    const rect = document.getElementById("chart-panel").getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    tooltip.innerHTML =
      '<div class="tt-ticker">' + escapeHtml(d.ticker) + "</div>" +
      '<div class="tt-name">' + escapeHtml(d.name) + "</div>" +
      '<div class="tt-sector">Sector: ' + escapeHtml(d.sector) + "</div>";
    tooltip.style.left = x + "px";
    tooltip.style.top = y + "px";
    tooltip.style.opacity = "1";
  }

  function onBubbleOut(tooltip) {
    tooltip.style.opacity = "0";
  }

  function selectTicker(ticker, opts) {
    const source = (opts && opts.source) || "table";
    state.selectedTicker = ticker;

    d3.selectAll("#bubble-chart circle.bubble").classed("is-selected", (d) => d.ticker === ticker);
    d3.selectAll("#bubble-chart circle.bubble").each(function (d) {
      if (d.ticker === ticker) {
        const node = this.parentNode;
        if (node && node.parentNode) {
          node.parentNode.appendChild(node);
        }
      }
    });

    const rows = document.querySelectorAll("#stock-table tbody tr");
    rows.forEach((tr) => {
      if (tr.dataset.ticker === ticker) {
        tr.classList.add("is-selected");
        if (source === "bubble") {
          tr.scrollIntoView({ behavior: "smooth", block: "nearest", inline: "nearest" });
        }
      } else {
        tr.classList.remove("is-selected");
      }
    });
  }

  function escapeHtml(s) {
    if (s === undefined || s === null) return "";
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }
})();

